import {useEffect,useMemo,useState,type ComponentProps} from 'react';
import {Alert,Image,Platform,Pressable,StyleSheet,Text,View} from '@/platform/react-native';
import {router,useLocalSearchParams} from '@/router';
import {useMutation,useQuery,useQueryClient} from '@tanstack/react-query';
import {Ionicons} from '@/platform/icons';
import * as ImagePicker from '@/platform/image-picker';
import {api} from '@/lib/api';
import {Badge,Button,Card,EmptyState,Input as BaseInput,Modal,Muted,Screen,TabBar,useAppTheme} from '@/components/UI';
import {DateField} from '@/components/DateField';
import {TimeField} from '@/components/TimeField';

function Input(props:ComponentProps<typeof BaseInput>){const raw=String(props.value||''),dateTime=String(props.placeholder||'').startsWith('Start:')||String(props.placeholder||'').startsWith('End:');if(!dateTime)return <BaseInput {...props}/>;const [date,time='18:00']=raw.split('T');return <View style={{flexDirection:'row',gap:8}}><View style={{flex:1}}><DateField value={date||''} onChange={d=>props.onChangeText?.(`${d}T${time.slice(0,5)||'18:00'}:00`)} minimumDate={new Date()}/></View><View style={{width:130}}><TimeField value={time.slice(0,5)} onChange={t=>props.onChangeText?.(`${date||new Date().toISOString().slice(0,10)}T${t}:00`)}/></View></View>}
type Event={Id:string;Title:string;Description?:string;EventType?:string;Location?:string;StartDateTime:string;EndDateTime:string;Capacity?:number;ReminderMinutes?:number;CoverImageUrl?:string;LastPhotoUrl?:string;ConversationId?:string;GoingCount?:number;WaitlistCount?:number;PhotoCount?:number;MyStatus?:'GOING'|'WAITLIST'|'NOT_GOING'};
type Tab='upcoming'|'mine'|'past'|'calendar';
export default function Events(){
 const{id,createEvent}=useLocalSearchParams<{id:string;createEvent?:string}>();const{palette}=useAppTheme();const qc=useQueryClient();const[tab,setTab]=useState<Tab>('upcoming'),[search,setSearch]=useState(''),[month,setMonth]=useState('All'),[createOpen,setCreateOpen]=useState(false),[title,setTitle]=useState(''),[desc,setDesc]=useState(''),[location,setLocation]=useState(''),[start,setStart]=useState(''),[end,setEnd]=useState(''),[cap,setCap]=useState(''),[eventType,setEventType]=useState('Community');
 const events=useQuery<Event[]>({queryKey:['events',id],queryFn:async()=>(await api.get(`/communities/${id}/events`)).data});const capabilities=useQuery<any>({queryKey:['capabilities',id],queryFn:async()=>(await api.get(`/communities/${id}/capabilities`)).data});const canCreate=!capabilities.isLoading;const data=events.data||[];
 const months=['All',...Array.from(new Set(data.map(x=>new Date(x.StartDateTime).toLocaleString(undefined,{month:'long',year:'numeric'}))))];
 const shown=useMemo(()=>{const now=Date.now(),q=search.trim().toLowerCase();return data.filter(e=>{const t=new Date(e.StartDateTime).getTime(),period=tab==='past'?t<now:tab==='mine'?t>=now&&!!e.MyStatus:t>=now;return period&&(month==='All'||new Date(e.StartDateTime).toLocaleString(undefined,{month:'long',year:'numeric'})===month)&&`${e.Title} ${e.Location||''} ${e.Description||''}`.toLowerCase().includes(q)})},[data,tab,month,search]);
 const rsvp=useMutation({mutationFn:async(v:{event:Event;status:'GOING'|'NOT_GOING'})=>(await api.post(`/events/${v.event.Id}/rsvp`,{status:v.status})).data,onSuccess:(d,v)=>{qc.invalidateQueries({queryKey:['events',id]});if(d.status==='WAITLIST')Alert.alert('Added to waitlist','This event is full. You will be notified if a place becomes available.');else Alert.alert(d.status==='GOING'?'RSVP confirmed':'RSVP updated',v.event.Title)},onError:(e:any)=>Alert.alert('Unable to RSVP',e.response?.data?.message||e.message)});
 const create=useMutation({mutationFn:()=>api.post(`/communities/${id}/events`,{title:title.trim(),description:desc.trim()||undefined,eventType,location:location.trim()||undefined,startDateTime:new Date(start).toISOString(),endDateTime:new Date(end).toISOString(),capacity:cap?Number(cap):undefined,allowWaitlist:true,reminderMinutes:60}),onSuccess:()=>{setCreateOpen(false);setTitle('');setDesc('');setLocation('');setStart('');setEnd('');setCap('');qc.invalidateQueries({queryKey:['events',id]});Alert.alert('Event created','Members can now discover and RSVP to this event.')},onError:(e:any)=>Alert.alert('Unable to create event',e.response?.data?.message||'Check the dates and required fields.')});
 async function calendar(e:Event){try{if(Platform.OS==='web'){const clean=(v:string)=>new Date(v).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const ics=`BEGIN:VCALENDAR\nVERSION:2.0\nBEGIN:VEVENT\nSUMMARY:${e.Title}\nDTSTART:${clean(e.StartDateTime)}\nDTEND:${clean(e.EndDateTime)}\nLOCATION:${e.Location||''}\nDESCRIPTION:${(e.Description||'').replace(/\n/g,' ')}\nEND:VEVENT\nEND:VCALENDAR`;const url=URL.createObjectURL(new Blob([ics],{type:'text/calendar'}));const a=document.createElement('a');a.href=url;a.download=`${e.Title.replace(/[^a-z0-9]+/gi,'-')}.ics`;a.click();URL.revokeObjectURL(url);return}const Calendar=await import('@/platform/calendar');const permission=await Calendar.requestCalendarPermissionsAsync();if(permission.status==='granted')await Calendar.createEventInCalendarAsync({title:e.Title,startDate:new Date(e.StartDateTime),endDate:new Date(e.EndDateTime),location:e.Location,notes:e.Description})}catch{Alert.alert('Calendar unavailable','The event could not be added to your device calendar.')}}
 async function photo(e:Event){try{const p=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],quality:.8});if(p.canceled)return;const x=p.assets[0],fd=new FormData();fd.append('file',{uri:x.uri,name:x.fileName||'event-photo.jpg',type:x.mimeType||'image/jpeg'} as any);const up=await api.post('/media/upload',fd,{headers:{'Content-Type':'multipart/form-data'}});await api.post(`/events/${e.Id}/photos`,{photoUrl:up.data.url});qc.invalidateQueries({queryKey:['events',id]})}catch(e:any){Alert.alert('Photo upload failed',e.response?.data?.message||e.message)}}
 const next=shown[0];
 useEffect(()=>{if(createEvent==='1'&&canCreate){setCreateOpen(true);router.setParams({createEvent:''} as any)}},[createEvent,canCreate]);
 return <Screen scroll contentStyle={s.page}><Card style={s.hero}><View style={[s.heroIcon,{backgroundColor:palette.successSoft}]}><Ionicons name="calendar" size={29} color={palette.success}/></View><View style={s.heroCopy}><Text style={[s.heroTitle,{color:palette.success}]}>Stay connected. Get involved.</Text><Muted>Discover events, RSVP, and stay connected with your community.</Muted></View></Card>
 <TabBar value={tab} onChange={setTab} items={[{key:'upcoming',label:'Upcoming',icon:'calendar-outline'},{key:'mine',label:'My Events',icon:'person-outline'},{key:'past',label:'Past Events',icon:'time-outline'},{key:'calendar',label:'Calendar',icon:'calendar-number-outline'}]}/>
 <View style={s.filters}><View style={[s.search,{borderColor:palette.border,backgroundColor:palette.surface}]}><Ionicons name="search-outline" size={20} color={palette.muted}/><Input value={search} onChangeText={setSearch} placeholder="Search events…" style={s.searchInput}/></View><Picker title="Month" label={month==='All'?'All Months':month} values={months} current={month} set={setMonth} palette={palette}/></View>
 {events.isLoading?<Muted>Loading events…</Muted>:shown.length?<>{tab!=='calendar'&&next?<><Text style={[s.sectionTitle,{color:palette.text}]}>Next Event</Text><Featured event={next} palette={palette} rsvp={(status)=>rsvp.mutate({event:next,status})} calendar={()=>calendar(next)} openChat={()=>next.ConversationId&&router.push(`/chat/${next.ConversationId}` as any)}/></>:null}<View style={s.sectionHead}><Text style={[s.sectionTitle,{color:palette.text}]}>{tab==='calendar'?'Event Calendar':tab==='past'?'Past Events':tab==='mine'?'My Events':'Upcoming Events'}</Text><Text style={{color:palette.primary,fontWeight:'800'}}>{shown.length} event{shown.length===1?'':'s'}</Text></View><Card style={s.list}>{shown.map(e=><EventRow key={e.Id} event={e} palette={palette} rsvp={(status)=>rsvp.mutate({event:e,status})} calendar={()=>calendar(e)} photo={()=>photo(e)} chat={()=>e.ConversationId&&router.push(`/chat/${e.ConversationId}` as any)}/>)}</Card></>:<EmptyState icon="calendar-number-outline" title={tab==='mine'?'No saved events':tab==='past'?'No past events':'No upcoming events'} body={canCreate?'Create a real community event to get started.':'Community events will appear here when administrators publish them.'}/>} 
 <Modal visible={createOpen} animationType="slide" presentationStyle="pageSheet" onRequestClose={()=>setCreateOpen(false)}><Screen scroll contentStyle={s.modal}><View style={s.modalHead}><View><Text style={[s.modalTitle,{color:palette.text}]}>Create Event</Text><Muted>Publish a real event for community members.</Muted></View><Pressable onPress={()=>setCreateOpen(false)} style={s.touch}><Ionicons name="close" size={27} color={palette.text}/></Pressable></View><Input value={title} onChangeText={setTitle} placeholder="Event title"/><Input value={desc} onChangeText={setDesc} placeholder="Description" multiline/><Input value={eventType} onChangeText={setEventType} placeholder="Category e.g. Meeting, Social, Volunteer"/><Input value={location} onChangeText={setLocation} placeholder="Location"/><Input value={start} onChangeText={setStart} placeholder="Start: 2026-09-12T18:00:00" autoCapitalize="none"/><Input value={end} onChangeText={setEnd} placeholder="End: 2026-09-12T20:00:00" autoCapitalize="none"/><Input value={cap} onChangeText={setCap} placeholder="Capacity (optional)" keyboardType="number-pad"/><Button title="Create Event" icon="calendar-outline" loading={create.isPending} disabled={title.trim().length<2||!start||!end||Number.isNaN(Date.parse(start))||Number.isNaN(Date.parse(end))} onPress={()=>create.mutate()}/></Screen></Modal></Screen>
}
function Picker({title,label,values,current,set,palette}:{title:string;label:string;values:string[];current:string;set:(x:string)=>void;palette:any}){const[open,setOpen]=useState(false);return <><Pressable accessibilityRole="button" accessibilityLabel={`Select ${title.toLowerCase()}`} onPress={()=>setOpen(true)} style={[s.picker,{borderColor:palette.border,backgroundColor:palette.surface}]}><Text numberOfLines={1} style={{color:current==='All'?palette.muted:palette.text,fontWeight:'800',flex:1}}>{label}</Text><Ionicons name="chevron-down" size={17} color={palette.text}/></Pressable><Modal visible={open} transparent animationType="fade" onRequestClose={()=>setOpen(false)}><Pressable style={s.selectorBackdrop} onPress={()=>setOpen(false)}><Pressable style={[s.selectorSheet,{backgroundColor:palette.surface}]} onPress={()=>{}}><View style={s.selectorHead}><Text style={[s.selectorTitle,{color:palette.text}]}>Select {title}</Text><Pressable accessibilityLabel="Close selector" onPress={()=>setOpen(false)} style={s.touch}><Ionicons name="close" size={24} color={palette.text}/></Pressable></View>{values.map(value=><Pressable key={value} onPress={()=>{set(value);setOpen(false)}} style={[s.selectorOption,{borderBottomColor:palette.border}]}><Text style={{color:palette.text,fontWeight:current===value?'900':'600',flex:1}}>{value==='All'?`All ${title==='Month'?'Months':'Categories'}`:value}</Text>{current===value?<Ionicons name="checkmark-circle" size={22} color={palette.primary}/>:null}</Pressable>)}</Pressable></Pressable></Modal></>}
function Featured({event,palette,rsvp,calendar,openChat}:{event:Event;palette:any;rsvp:(x:'GOING'|'NOT_GOING')=>void;calendar:()=>void;openChat:()=>void}){const d=new Date(event.StartDateTime);return <Card style={s.featured}>{event.LastPhotoUrl||event.CoverImageUrl?<Image source={{uri:event.LastPhotoUrl||event.CoverImageUrl}} style={s.featureImage}/>:<View style={[s.featureImage,s.placeholder]}><Ionicons name="calendar" size={55} color={palette.success}/></View>}<View style={s.dateBlock}><Text style={s.month}>{d.toLocaleString(undefined,{month:'short'}).toUpperCase()}</Text><Text style={s.day}>{d.getDate()}</Text><Text style={s.weekday}>{d.toLocaleString(undefined,{weekday:'short'}).toUpperCase()}</Text></View><View style={s.featureBody}><Badge text={event.EventType||'EVENT'} tone="green"/><Text style={[s.featureTitle,{color:palette.text}]}>{event.Title}</Text><Muted>◷ {d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} – {new Date(event.EndDateTime).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</Muted><Muted>⌖ {event.Location||'Location to be confirmed'}</Muted><Muted>{event.GoingCount||0} going{event.WaitlistCount?` · ${event.WaitlistCount} waiting`:''}</Muted><View style={s.buttons}><Button title={event.MyStatus==='GOING'?'Going ✓':'RSVP Going'} variant="success" onPress={()=>rsvp('GOING')}/><Button title="Calendar" variant="secondary" onPress={calendar}/>{event.ConversationId?<Button title="Chat" variant="ghost" onPress={openChat}/>:null}</View></View></Card>}
function EventRow({event,palette,rsvp,calendar,photo,chat}:{event:Event;palette:any;rsvp:(x:'GOING'|'NOT_GOING')=>void;calendar:()=>void;photo:()=>void;chat:()=>void}){const d=new Date(event.StartDateTime);return <View style={[s.eventRow,{borderBottomColor:palette.border}]}><View style={[s.rowDate,{backgroundColor:palette.primarySoft}]}><Text style={{color:palette.primary,fontWeight:'900'}}>{d.toLocaleString(undefined,{month:'short'}).toUpperCase()}</Text><Text style={{color:palette.primary,fontSize:25,fontWeight:'900'}}>{d.getDate()}</Text><Text style={{color:palette.primary,fontSize:11}}>{d.toLocaleString(undefined,{weekday:'short'}).toUpperCase()}</Text></View>{event.LastPhotoUrl||event.CoverImageUrl?<Image source={{uri:event.LastPhotoUrl||event.CoverImageUrl}} style={s.thumb}/>:null}<View style={{flex:1}}><Text style={[s.rowTitle,{color:palette.text}]}>{event.Title}</Text><Muted>{d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} · {event.Location||'Location TBC'}</Muted><View style={s.inline}><Badge text={event.MyStatus||`${event.GoingCount||0} going`} tone={event.MyStatus==='GOING'?'green':'gray'}/><Pressable onPress={()=>rsvp(event.MyStatus==='GOING'?'NOT_GOING':'GOING')}><Text style={{color:palette.primary,fontWeight:'800'}}>{event.MyStatus==='GOING'?'Cancel RSVP':'RSVP'}</Text></Pressable><Pressable onPress={calendar}><Ionicons name="calendar-outline" size={20} color={palette.primary}/></Pressable><Pressable onPress={photo}><Ionicons name="image-outline" size={20} color={palette.primary}/></Pressable>{event.ConversationId?<Pressable onPress={chat}><Ionicons name="chatbubble-outline" size={20} color={palette.primary}/></Pressable>:null}</View></View></View>}
const s=StyleSheet.create({page:{width:'100%',maxWidth:920,alignSelf:'center',paddingBottom:125},touch:{minWidth:44,minHeight:44,alignItems:'center',justifyContent:'center'},hero:{flexDirection:'row',alignItems:'center',gap:10,padding:14},heroIcon:{width:56,height:56,borderRadius:28,alignItems:'center',justifyContent:'center'},heroCopy:{flex:1,minWidth:0},heroTitle:{fontSize:16,fontWeight:'900',marginBottom:3},tabs:{flexDirection:'row',borderWidth:1,borderRadius:16,overflow:'hidden',marginVertical:12},tab:{flex:1,minHeight:48,borderBottomWidth:3,borderBottomColor:'transparent',alignItems:'center',justifyContent:'center'},filters:{flexDirection:'row',gap:8,marginBottom:14,width:'100%'},search:{minHeight:48,flex:1,minWidth:0,borderWidth:1,borderRadius:12,flexDirection:'row',alignItems:'center',paddingHorizontal:11},searchInput:{flex:1,borderWidth:0,marginBottom:0,backgroundColor:'transparent'},picker:{width:'38%',minWidth:128,maxWidth:180,minHeight:48,borderWidth:1,borderRadius:12,flexDirection:'row',alignItems:'center',paddingHorizontal:12},selectorBackdrop:{flex:1,backgroundColor:'rgba(5,20,15,.45)',justifyContent:'flex-end'},selectorSheet:{width:'100%',maxWidth:560,alignSelf:'center',borderTopLeftRadius:22,borderTopRightRadius:22,padding:18,paddingBottom:34,maxHeight:'75%'},selectorHead:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginBottom:4},selectorTitle:{fontSize:19,fontWeight:'900'},selectorOption:{minHeight:52,flexDirection:'row',alignItems:'center',borderBottomWidth:1,paddingHorizontal:4},sectionTitle:{fontSize:17,fontWeight:'900',marginVertical:12},sectionHead:{flexDirection:'row',alignItems:'center',justifyContent:'space-between'},featured:{padding:0,overflow:'hidden',flexDirection:'row',minHeight:220},featureImage:{width:'38%',minHeight:220},placeholder:{alignItems:'center',justifyContent:'center',backgroundColor:'#FFFFFF'},dateBlock:{position:'absolute',left:0,top:0,width:76,padding:9,alignItems:'center',backgroundColor:'#0F8A43',borderBottomRightRadius:16},month:{color:'#fff',fontWeight:'900'},day:{color:'#fff',fontSize:27,fontWeight:'900'},weekday:{color:'#fff',fontSize:11},featureBody:{flex:1,padding:18,gap:6},featureTitle:{fontSize:20,fontWeight:'900'},buttons:{flexDirection:'row',gap:7,flexWrap:'wrap',marginTop:8},list:{paddingVertical:0,overflow:'hidden'},eventRow:{minHeight:130,flexDirection:'row',alignItems:'center',gap:12,borderBottomWidth:1,paddingVertical:12},rowDate:{width:68,minHeight:88,borderRadius:13,alignItems:'center',justifyContent:'center'},thumb:{width:126,height:90,borderRadius:12},rowTitle:{fontSize:16,fontWeight:'900'},inline:{flexDirection:'row',alignItems:'center',gap:12,flexWrap:'wrap',marginTop:9},modal:{width:'100%',maxWidth:720,alignSelf:'center'},modalHead:{flexDirection:'row',justifyContent:'space-between',alignItems:'center',marginBottom:14},modalTitle:{fontSize:23,fontWeight:'900'}});
